{
  "tasks": [
    {
      "task_id": "T1",
      "title": "已完成任务的项目分布及数量统计",
      "business_question": "按项目统计已完成任务的数量，并按数量降序排列。仅分析状态为“已完成”的任务。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标：了解哪些项目完成了更多任务，支持资源或进度决策。删除此任务将无法获取任何关于已完成任务分布的信息。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "completed_task_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "completed_task_count",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
